<script setup lang="ts">
import { computed, ref } from 'vue';import { useForm } from '@inertiajs/vue3'; import BaseLayout from '../../layouts/BaseLayout.vue';import BaseCard from '../../components/BaseCard.vue';import HostNav from '../../components/hote/HostNav.vue';import GuestForm,{type Guest,type HostChoice,type CategoryChoice} from '../../components/hote/GuestForm.vue';
const props=defineProps<{visitor:Guest;hosts:HostChoice[];categories:CategoryChoice[];arrived:boolean;feedback?:string|null;visit:{expected_at:string|null};vehicles:{id:string;plate:string;kind:string;status:string}[];kinds:Record<string,string>}>();const removing=ref(false);const form=useForm({});
const toLocal=(v:string|null)=>v?v.slice(0,16).replace(' ','T'):'';const announce=useForm({expected_at:toLocal(props.visit.expected_at)});const vehicle=useForm({plate:'',kind:'voiture'});
const announceError=computed(()=>announce.errors.expected_at||(announce.errors as Record<string,string>).participation);const vehicleError=computed(()=>vehicle.errors.plate||(vehicle.errors as Record<string,string>).participation);
</script>
<template><BaseLayout><HostNav /><h1 class="mb-5 text-display font-bold">Mon invité</h1><p v-if="feedback" role="status" class="mb-4">{{ feedback }}</p><BaseCard><GuestForm :visitor="visitor" :hosts="hosts" :categories="categories" :locked="arrived" /><template v-if="!arrived"><button v-if="!removing" class="btn-no mt-6" @click="removing=true">Retirer cet invité</button><div v-else class="mt-6 space-y-4 rounded border-2 border-ikoma-danger p-4"><p>Retirer cet invité de votre liste ? Il ne pourra plus être traité à l’accueil.</p><button class="btn-no" :disabled="form.processing" @click="form.delete('/hote/invites/'+props.visitor.id)">Confirmer le retrait</button><button class="btn-soft" @click="removing=false">Annuler</button></div><p v-for="(error,key) in form.errors" :key="key" role="alert">{{ error }}</p></template></BaseCard><BaseCard v-if="!arrived" data-testid="annonce-visite"><h2 class="text-heading font-bold">Visite annoncée</h2><p>Indiquez l’heure à laquelle votre invité est attendu. Cela ne vaut pas présence : l’accueil l’admet à son arrivée.</p><form class="space-y-3" @submit.prevent="announce.post('/hote/invites/'+props.visitor.id+'/annonce',{preserveScroll:true})"><label class="block text-lg font-semibold">Heure d’arrivée attendue<input v-model="announce.expected_at" type="datetime-local" class="field" required data-testid="heure-attendue"></label><button class="btn-main" :disabled="announce.processing||!announce.expected_at" data-testid="annoncer">Annoncer la visite</button><p v-if="announceError" role="alert">{{ announceError }}</p></form></BaseCard><BaseCard v-if="!arrived" data-testid="vehicules-invite"><h2 class="text-heading font-bold">Véhicule de l’invité</h2><ul><li v-for="x in vehicles" :key="x.id" class="flex items-center gap-3"><strong>{{ x.plate }}</strong> · {{ kinds[x.kind]||x.kind }}<button v-if="x.status==='annonce'" type="button" class="btn-soft !w-auto" @click="form.delete('/hote/vehicules/'+x.id,{preserveScroll:true})">Annuler</button></li></ul><form class="space-y-3" @submit.prevent="vehicle.post('/hote/invites/'+props.visitor.id+'/vehicules',{preserveScroll:true,onSuccess:()=>vehicle.reset('plate')})"><label class="block text-lg font-semibold">Plaque d’immatriculation<input v-model="vehicle.plate" class="field uppercase" maxlength="20" required data-testid="plaque"></label><label class="block text-lg font-semibold">Type de véhicule<select v-model="vehicle.kind" class="field" data-testid="type-vehicule"><option v-for="(label,key) in kinds" :key="key" :value="key">{{ label }}</option></select></label><button class="btn-main" :disabled="vehicle.processing||!vehicle.plate.trim()" data-testid="ajouter-vehicule">Annoncer le véhicule</button><p v-if="vehicleError" role="alert">{{ vehicleError }}</p></form></BaseCard></BaseLayout></template>
